// MAMALookback returns how many leading bars [Core.MAMA] consumes before its
// first value: called with startIdx 0, its first value is at that bar.
//
// The lookback includes the unstable period the Core holds for FuncUnstIdMAMA
// (see [Core.SetUnstablePeriod]).
//
// It takes the parameters of [Core.MAMA] and returns [BadParam] for one out of
// range.
func (c *Core) MAMALookback(optInFastLimit, optInSlowLimit float64) (int, error) {
	lookback := c.mamaLookback(optInFastLimit, optInSlowLimit)
	if lookback < 0 {
		return 0, BadParam
	}
	return int(lookback), nil
}

// MAMA computes the MESA Adaptive Moving Average over bars startIdx through
// endIdx.
//
// MESA Adaptive Moving Average: an adaptive EMA whose smoothing factor is
// driven by the dominant-cycle phase rate measured with a Hilbert transform.
// Emits two lines, MAMA and its slower follower FAMA. MAMA crossing above FAMA
// is bullish; crossing below is bearish.
//
// Formula and more info at https://ta-lib.org/functions/mama.
//
// Inputs, each at least endIdx+1 long:
//   - inReal: Price series to smooth.
//
// Parameters:
//   - optInFastLimit: Upper bound on the adaptive smoothing factor. Default
//     0.5; range 0.01 to 0.99; RealDefault selects the default.
//   - optInSlowLimit: Lower bound on the adaptive smoothing factor. Default
//     0.05; range 0.01 to 0.99; RealDefault selects the default.
