// OutRange returns the bars the stream has a value for, as [Core.MAMA] reports
// them over the same bars; each Update and each Advance adds one to NBElement.
func (sp *MAMAStream) OutRange() OutRange {
	return OutRange{BegIdx: sp.outRangeBegIdx, NBElement: sp.outRangeCount}
}

// Advance counts one bar the stream was not fed: OutRange grows by one and
// Value keeps its previous answer. It returns [OutOfRangeEndIndex] once
// OutRange reaches bar [IndexMax].
func (sp *MAMAStream) Advance() error {
	if sp.outRangeBegIdx+sp.outRangeCount > IndexMax {
		return OutOfRangeEndIndex
	}
	sp.outRangeCount++
	return nil
}

